@import "../../styles/tokens.css";

/* ===== BACKDROP ===== */
.clean-modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
  animation: fadeIn 0.2s ease-out;
}

.clean-modal-backdrop.mobile {
  padding: 0;
  align-items: flex-end;
  background: rgba(0, 0, 0, 0.4);
}

/* ===== MODAL CONTAINER ===== */
.clean-modal-container {
  position: relative;
  background: #ffffff;
  border: 1.5px solid var(--vt-border);
  border-radius: 12px;
  width: 60vw;
  max-width: 800px;
  min-width: 300px;
  padding: 1.5rem 2rem;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  max-height: 90vh;
}

/* Opt-in wider variant for data-dense content (tables, bulk pickers),
   pass size="large" to Modal. Every other caller is unaffected. */
.clean-modal-container.large {
  width: 90vw;
  max-width: 1100px;
  align-items: stretch;
}

/* ===== MOBILE BOTTOM SHEET STYLES ===== */
.clean-modal-container.mobile {
  width: 100%;
  max-width: 100%;
  min-width: 100%;
  border-radius: 24px 24px 0 0;
  padding: 0.5rem 0.7rem 0.5rem;
  max-height: 95vh;
  min-height: 30vh;
  touch-action: none; /* Prevent scroll interference during drag; border comes from the base .clean-modal-container rule */
}

/* ===== DRAG HANDLE ===== */
.modal-drag-handle-container {
  width: 100%;
  padding: 0.75rem 0;
  display: flex;
  justify-content: center;
  cursor: grab;
  touch-action: none;
}

.modal-drag-handle-container:active {
  cursor: grabbing;
}

.modal-drag-handle {
  /* width: 40px;
  height: 5px; */
  background: #d1d5db;
  /* border-radius: 999px;
  transition: background 0.2s ease, width 0.2s ease; */
}

